# application.properties - Basic production tuning
server.port=8080
server.tomcat.threads.max=300
server.tomcat.threads.min-spare=50
server.tomcat.max-connections=10000
server.tomcat.accept-count=200
server.tomcat.connection-timeout=25000

@Configuration
class TomcatCustomizer {
    @Bean
    public WebServerFactoryCustomizer<TomcatServletWebServerFactory> customizer() {
        return factory -> {
            factory.addConnectorCustomizers(connector -> {
                var protocol = (Http11NioProtocol) connector.getProtocolHandler();
                protocol.setMaxKeepAliveRequests(100); // Keep-alive requests per connection
                protocol.setKeepAliveTimeout(60000); // Keep connection open 60 seconds
            });
        };
    }
}
