@Component
class ServerReadyListener {
    private static final Logger log = LoggerFactory.getLogger(ServerReadyListener.class);

    @EventListener(ServletWebServerInitializedEvent.class)
    public void onServerReady(ServletWebServerInitializedEvent event) {
        int port = event.getWebServer().getPort();
        log.info("Embedded server started on port: {}", port);
        // Safe to make health check calls or register with service discovery here
    }

    @PreDestroy
    public void onShutdown() {
        log.info("Application shutting down, server already stopped accepting requests");
    }
}
